function init(){defaults({constraint:'主角不使用暴力；伙伴不独自离开',drafts:[]});if(!state.nodes[state.current])state.current='start'}init();
const storyText=s=>esc(String(s||'').replaceAll('{hero}',state.hero).replaceAll('{partner}',state.partner));
function graphCheck(){const seen=new Set(),missing=new Set();function walk(id){if(seen.has(id))return;seen.add(id);const n=state.nodes[id];if(!n){missing.add(id);return}for(const c of n.choices||[])walk(c.next)}walk('start');return {missing:[...missing],unreachable:Object.keys(state.nodes).filter(x=>!seen.has(x)),endings:Object.entries(state.nodes).filter(([id,x])=>x.ending&&seen.has(id))}}
function nodeEditor(id){const n=state.nodes[id];editModal('改写这一幕',field('这一幕的名字','title','text',n.title,'required maxlength="60"')+textfield('发生了什么','text',n.text)+`<p class="hint">可以使用 {hero} 和 {partner}，会自动替换成角色代号。</p>`+(n.ending?textfield('留给读者的一句话','lesson',n.lesson||'',300):''),v=>{Object.assign(n,v);commit('这一幕已改写')});}
function branchEditor(id){editModal('添加一个新选择',field('读者可以怎样选择','label','text','','required maxlength="100"')+field('这个选择走向的结局名称','title','text','','required maxlength="60"')+textfield('选择之后发生了什么','text')+textfield('这个结局带来的思考','lesson','',300),v=>{const next='node-'+uid();state.nodes[next]={title:v.title,text:v.text,lesson:v.lesson,ending:true};state.nodes[id].choices??=[];state.nodes[id].choices.push({label:v.label,next});commit('新选择和结局已连接，可以试读啦')},'连接这个新结局')}
function removableNode(id){return id!=='start'&&!Object.values(state.nodes).some(n=>(n.choices||[]).some(c=>c.next===id))}
function choiceEditor(key){const[id,index]=key.split(':');const choices=state.nodes[id].choices,c=choices[+index];editModal('修改读者的选择',field('选择文字','label','text',c.label,'required maxlength="100"')+`<label>接着走向哪一幕<select name="next">${Object.entries(state.nodes).map(([k,n])=>`<option value="${esc(k)}" ${k===c.next?'selected':''}>${esc(n.title)}</option>`).join('')}</select></label>`,v=>{Object.assign(c,v);commit('选择已更新，记得再试读一次')});$('#edit-form').insertAdjacentHTML('beforeend',btn('移除这个选择','remove-choice','danger',choices.length<=1));on('remove-choice',()=>{if(choices.length<=1)return;choices.splice(+index,1);closeModal();commit('选择已移除，可撤销')})}
function render(){nav();const node=state.nodes[state.current],g=graphCheck();
if(active===0){$('#app').innerHTML=`<div class="two-col"><div><section class="card story-stage"><span class="eyebrow">${esc(state.theme)} · 第 ${state.path.length+1} 幕</span>${art('story')}<h2>${esc(node.title)}</h2><p style="margin-top:16px">${storyText(node.text)}</p></section>${node.ending?`<section class="notice" style="margin-top:18px">${storyText(node.lesson)}</section><div style="margin-top:16px">${btn('回到开头，试试另一种选择','restart','primary full')}</div>`:(node.choices||[]).map((c,i)=>`<button class="choice" data-choice="${i}"><span>${String.fromCharCode(65+i)}</span>${storyText(c.label)}</button>`).join('')}</div><aside class="stack"><section class="card"><span class="eyebrow">导演手记</span><h3 style="margin:12px 0">每个选择，都有下一幕</h3><p class="hint">${esc(p.constraint)}</p>${progress(state.endings.length/Math.max(1,g.endings.length)*100,'结局发现进度')}<p class="hint">已发现 ${state.endings.filter(id=>state.nodes[id]?.ending).length} / ${g.endings.length} 个结局</p></section><section class="card"><h3>走过的故事</h3>${state.path.length?state.path.map((s,i)=>`<p class="hint" style="margin-top:12px">${i+1}. ${storyText(s)}</p>`).join(''):'<p class="hint" style="margin-top:12px">故事刚刚开始，做出你的第一个选择。</p>'}</section></aside></div>`;actions('choice',i=>{const c=node.choices[+i];if(!state.nodes[c.next])return toast('这个选择还没有连接下一幕，请到分镜中检查');if(state.path.length>=100)return toast('这条路线有点长，回到开头再探索吧');state.path.push(c.label);state.current=c.next;if(state.nodes[c.next].ending&&!state.endings.includes(c.next))state.endings.push(c.next);commit('');window.scrollTo({top:0,behavior:'instant'})});on('restart',()=>{state.current='start';state.path=[];commit('');window.scrollTo({top:0,behavior:'instant'})})}
if(active===1){$('#app').innerHTML=`<div class="two-col"><div>${heading('故事分镜')}<p class="notice">${g.missing.length||g.unreachable.length?'有分镜未连接，请检查下方路线。':`路线检查通过 · ${Object.keys(state.nodes).length} 幕 · ${g.endings.length} 个可到达的结局`}</p>${Object.entries(state.nodes).map(([id,n])=>`<article class="node"><div class="between"><h3>${esc(n.title)}</h3><span class="pill">${g.unreachable.includes(id)?'尚未连接':n.ending?'结局':'情节'}</span></div><p>${storyText(n.text)}</p>${(n.choices||[]).map((c,i)=>`<div class="subtle" style="margin:8px 0">${storyText(c.label)}<br>↳ ${esc(state.nodes[c.next]?.title||'未连接')}<br><button data-choiceedit="${id}:${i}">修改选择</button></div>`).join('')}<div class="row"><button data-edit="${id}" class="secondary">改写这一幕</button>${g.unreachable.includes(id)&&removableNode(id)?`<button data-removenode="${id}" class="danger">移除未连接分镜</button>`:''}${!n.ending?`<button data-branch="${id}">＋ 新选择</button>`:''}</div></article>`).join('')}</div><aside class="card"><h3>写完，一定要试读</h3><p class="hint" style="margin:12px 0">试一遍每个选择，看看是否真的能走到结局。自动检查只验证路线，角色有没有遵守约定，需要你自己判断。</p>${btn('从头试读','preview','primary full')}</aside></div>`;actions('edit',nodeEditor);actions('branch',branchEditor);actions('choiceedit',choiceEditor);actions('removenode',id=>{if(!removableNode(id)||!g.unreachable.includes(id))return;delete state.nodes[id];if(state.current===id){state.current='start';state.path=[]}state.endings=state.endings.filter(x=>x!==id);commit('未连接分镜已移除，可撤销')});on('preview',()=>{state.current='start';state.path=[];save();go(0)})}
if(active===2){$('#app').innerHTML=`<div class="two-col"><section class="card"><h2>故事由你定义</h2><form id="cast" class="stack" style="margin-top:22px"><div class="fields">${field('主角代号','hero','text',state.hero,'required maxlength="20"')}${field('伙伴代号','partner','text',state.partner,'required maxlength="20"')}</div>${field('故事名称','theme','text',state.theme,'required maxlength="40"')}${textfield('角色必须遵守的约定','constraint',p.constraint,300)}<button class="primary">保存角色设定</button></form></section><aside class="card"><h3>和 AI 一起想，再由你执导</h3><p class="hint" style="margin:12px 0">先写好角色约束，再把下方提示词交给课堂使用的 AI。把你挑选、修改过的内容写进分镜。</p><div class="subtle" id="prompt-text">请为“${esc(state.theme)}”设计一个有后果的选择和结局。主角：${esc(state.hero)}；伙伴：${esc(state.partner)}。必须遵守：${esc(p.constraint)}。请给出选择文字、结局标题、情节和思考，不使用暴力解决问题。</div><p class="hint" style="margin-top:16px">本 Demo 不直接调用在线 AI；你可以完整地编辑、连接和试读故事。</p></aside></div>`;form('cast',v=>{state.hero=v.hero;state.partner=v.partner;state.theme=v.theme;p.constraint=v.constraint;commit('角色设定已保存')})}}
shell([['试读','book'],['分镜','graph'],['角色','people']]);render();
